1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.Normalizer;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Attribute;
6	import org.jsoup.nodes.Element;
7	
8	import java.util.ArrayList;
9	import java.util.Collections;
10	import java.util.List;
11	import java.util.Set;
12	
13	/**
14	 Validates and rewrites {@code srcset} attributes, one image candidate at a time.
15	 <p>
16	 The attribute value is split into candidates following the HTML {@code srcset} parsing rules: a candidate consists of a
17	 URL followed by an optional width ({@code w}) or pixel density ({@code x}) descriptor. Commas only separate
18	 candidates at a candidate boundary, so commas nested inside a {@code data:} URL, a quoted value, or entity-decoded
19	 content are preserved. A candidate address may be wrapped in matching {@code "} or {@code '} quotes; the commas,
20	 whitespace, character references, and parentheses inside are literal address content, but the delimiting quotes are
21	 syntax only and never appear in the cleaned output. Each surviving URL is checked against the safelist with the same
22	 protocol and encoding rules used for ordinary URI attributes such as {@code src}; an invalid descriptor, or an
23	 address whose bare spelling cannot be reparsed as that same single candidate, invalidates only that candidate and
24	 never the other candidates in the attribute.
25	 </p>
26	 */
27	final class SrcsetCleaner {
28	    private SrcsetCleaner() {}
29	
30	    private static final int InDescriptor = 1;
31	    private static final int InParens = 2;
32	    private static final int AfterDescriptor = 3;
33	
34	    /**
35	     Determine whether the supplied attribute is a {@code srcset} attribute that should be handled candidate by
36	     candidate, rather than treated as an ordinary opaque attribute.
37	     @param attr the attribute to test
38	     @return true if it is a {@code srcset} attribute
39	     */
40	    static boolean isSrcset(Attribute attr) {
41	        return "srcset".equalsIgnoreCase(attr.getKey());
42	    }
43	
44	    /**
45	     Clean a {@code srcset} attribute value into a value containing only the acceptable candidates, in their original
46	     order. The input element is not modified; callers must apply the result themselves.
47	     @param el the element carrying the attribute (used for URL resolution against its base URI)
48	     @param rawValue the original attribute value
49	     @param safelist the safelist to validate each candidate URL against
50	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no candidate survived, in
51	     which case the attribute must be removed rather than left empty
52	     */
53	    static Result clean(Element el, String rawValue, Safelist safelist) {
54	        List<Candidate> accepted = new ArrayList<>();
55	        int dropped = 0;
56	        if (rawValue != null && !rawValue.isEmpty()) {
57	            int pos = 0;
58	            int len = rawValue.length();
59	
60	            while (pos < len) {
61	                // 1. Splitting loop: skip a run of ASCII whitespace and candidate-separating commas. Empty items,
62	                //    consecutive commas, and trailing separators are consumed here and never raise an error.
63	                while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
64	                if (pos >= len) break;
65	
66	                // 2. Collect the URL and whatever descriptor tokens follow it. A URL run may be wrapped in matching
67	                //    quotes, in which case its commas and whitespace are literal address content.
68	                UrlRun run = collectUrl(rawValue, pos);
69	                pos = run.nextPos;
70	                if (!run.valid) { // malformed quoted run: drop this item, keep parsing any later candidates
71	                    dropped++;
72	                    continue;
73	                }
74	                String url = run.url;
75	
76	                if (url.isEmpty()) continue;
77	
78	                String descriptor = parseDescriptors(run.descriptors);
79	                String safeUrl = (descriptor != null) ? isSafeUrl(el, url, safelist) : null;
80	                // Quotes were parse-time delimiters only, so the output is always the bare address. A bare spelling
81	                // that would not reparse into this same single candidate cannot be emitted and is dropped alone.
82	                if (safeUrl != null && isBareSerializable(safeUrl))
83	                    accepted.add(new Candidate(safeUrl, descriptor));
84	                else
85	                    dropped++;
86	            }
87	        }
88	
89	        if (accepted.isEmpty()) return new Result(null, dropped, true);
90	        return new Result(serialize(accepted), dropped, false);
91	    }
92	
93	    /** The outcome of cleaning a srcset attribute: the rewritten {@code value} (or null) and statistics. */
94	    static final class Result {
95	        final String value;
96	        final int droppedCandidates;
97	        final boolean removed;
98	
99	        private Result(String value, int droppedCandidates, boolean removed) {
100	            this.value = value;
101	            this.droppedCandidates = droppedCandidates;
102	            this.removed = removed;
103	        }
104	    }
105	
106	    private static final class TokenizerResult {
107	        final List<String> tokens;
108	        final int nextPos; // position just past the candidate-separating comma, or at end of input
109	
110	        private TokenizerResult(List<String> tokens, int nextPos) {
111	            this.tokens = tokens;
112	            this.nextPos = nextPos;
113	        }
114	    }
115	
116	    /** One collected candidate: the decoded URL, its descriptor tokens, and where parsing should continue. */
117	    private static final class UrlRun {
118	        final String url;
119	        final List<String> descriptors;
120	        final int nextPos;
121	        final boolean valid; // false for a malformed quoted run (junk after the quote, or an unterminated quote)
122	
123	        private UrlRun(String url, List<String> descriptors, int nextPos, boolean valid) {
124	            this.url = url;
125	            this.descriptors = descriptors;
126	            this.nextPos = nextPos;
127	            this.valid = valid;
128	        }
129	    }
130	
131	    /**
132	     Collect one candidate starting at {@code start}: its URL run and the descriptor tokens that follow it.
133	     <p>
134	     A run whose first character is a matching {@code "} or {@code '} is quoted: the address runs to the closing
135	     delimiter, so embedded commas, whitespace, and decoded character references are literal address content rather
136	     than candidate boundaries. The delimiter itself never becomes part of the address. The closing quote may be
137	     followed by whitespace introducing descriptors, a boundary comma, or end of input; any other character glued
138	     directly to the quote invalidates the candidate. An unterminated quote drops that item, and parsing resyncs at
139	     the next candidate comma so any following valid candidate is still considered.
140	     </p>
141	     */
142	    private static UrlRun collectUrl(String input, int start) {
143	        int len = input.length();
144	        char first = input.charAt(start);
145	
146	        if (first == '"' || first == '\'') {
147	            char quote = first;
148	            int contentStart = start + 1;
149	            int p = contentStart;
150	            while (p < len && input.charAt(p) != quote) p++;
151	            if (p >= len) {
152	                // Unterminated quote: the malformed item is dropped, but a later comma still resyncs parsing so a
153	                // following valid candidate is not swallowed. Without a comma there is nothing more to recover.
154	                int comma = input.indexOf(',', contentStart);
155	                int nextPos = comma >= 0 ? comma + 1 : len;
156	                return new UrlRun(input.substring(contentStart), Collections.emptyList(), nextPos, false);
157	            }
158	            String url = input.substring(contentStart, p);
159	            p++; // the closing quote
160	
161	            int q = p;
162	            boolean separated = false;
163	            while (q < len && StringUtil.isWhitespace(input.charAt(q))) { q++; separated = true; }
164	
165	            if (q < len && input.charAt(q) == ',') {
166	                return new UrlRun(url, Collections.emptyList(), q + 1, true);
167	            }
168	            if (q == len) {
169	                return new UrlRun(url, Collections.emptyList(), q, true);
170	            }
171	            // Descriptor tokens begin here; they are legal only after whitespace separating them from the quote.
172	            // Tokenize regardless so that the boundary comma (if any) is consumed and later candidates survive.
173	            TokenizerResult tokenized = tokenizeDescriptors(input, q);
174	            return new UrlRun(url, tokenized.tokens, tokenized.nextPos, separated);
175	        }
176	
177	        // Unquoted URL: a run of non-whitespace characters.
178	        int urlStart = start;
179	        int pos = start;
180	        while (pos < len && !StringUtil.isWhitespace(input.charAt(pos))) pos++;
181	        int urlRunEnd = pos;
182	        int urlEnd = urlRunEnd;
183	        while (urlEnd > urlStart && input.charAt(urlEnd - 1) == ',') urlEnd--;
184	        String url = input.substring(urlStart, urlEnd);
185	
186	        if (urlEnd < urlRunEnd) {
187	            // The URL run ended in comma(s) with no whitespace: the boundary has no descriptor and parsing restarts
188	            // at the splitting loop. This is what keeps a comma inside a data: URL (e.g. "data:,Hello") in the URL.
189	            return new UrlRun(url, Collections.emptyList(), urlRunEnd, true);
190	        }
191	        // Tokenize the descriptors with the HTML srcset state machine, so that a comma nested in a parenthesized
192	        // (or quoted) descriptor does not get mistaken for a candidate boundary.
193	        TokenizerResult tokenized = tokenizeDescriptors(input, pos);
194	        return new UrlRun(url, tokenized.tokens, tokenized.nextPos, true);
195	    }
196	
197	    private static boolean isWsOrComma(char c) {
198	        return c == ',' || StringUtil.isWhitespace(c);
199	    }
200	
201	    /**
202	     Run the HTML srcset descriptor tokenizer starting at the first character after the URL's whitespace run.
203	     Parenthesized content (and anything quoted within it) is taken verbatim, so commas and whitespace inside it
204	     cannot start a new candidate. Stops at a boundary comma (consumed) or end of input.
205	     */
206	    private static TokenizerResult tokenizeDescriptors(String input, int pos) {
207	        List<String> tokens = new ArrayList<>();
208	        int len = input.length();
209	        int state = InDescriptor;
210	        StringBuilder token = new StringBuilder();
211	
212	        while (pos < len) {
213	            char c = input.charAt(pos);
214	            switch (state) {
215	                case InDescriptor:
216	                    if (StringUtil.isWhitespace(c)) {
217	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
218	                        state = AfterDescriptor;
219	                    } else if (c == ',') {
220	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
221	                        return new TokenizerResult(tokens, pos + 1); // consume the candidate separator
222	                    } else if (c == '(') {
223	                        token.append(c);
224	                        state = InParens;
225	                    } else {
226	                        token.append(c);
227	                    }
228	                    pos++;
229	                    break;
230	                case InParens:
231	                    token.append(c); // commas, whitespace, and quotes in here are all literal
232	                    if (c == ')') state = InDescriptor;
233	                    pos++;
234	                    break;
235	                case AfterDescriptor:
236	                    if (StringUtil.isWhitespace(c)) {
237	                        pos++;
238	                    } else if (c == ',') {
239	                        return new TokenizerResult(tokens, pos + 1);
240	                    } else {
241	                        state = InDescriptor; // reprocess this character as a new token
242	                    }
243	                    break;
244	            }
245	        }
246	        if (token.length() > 0) tokens.add(token.toString());
247	        return new TokenizerResult(tokens, pos);
248	    }
249	
250	    /**
251	     Validate the tokenized descriptor list of one candidate. Legal forms are: no descriptor, a single strictly
252	     positive width ({@code <integer>w}), or a single finite strictly-positive pixel density ({@code <number>x}).
253	     Duplicated, unknown, parenthesized, or syntactically invalid descriptors invalidate the candidate.
254	     @return the normalized descriptor suffix ({@code ""} when absent, or {@code " <descriptor>"}), or {@code null}
255	     */
256	    private static String parseDescriptors(List<String> tokens) {
257	        if (tokens.isEmpty()) return "";
258	        if (tokens.size() > 1) return null;
259	
260	        String descriptor = tokens.get(0);
261	        if (descriptor.isEmpty()) return "";
262	        char suffix = descriptor.charAt(descriptor.length() - 1);
263	        if (suffix != 'w' && suffix != 'x') return null; // only lower-case width/density descriptors are valid
264	        String number = descriptor.substring(0, descriptor.length() - 1);
265	        if (number.isEmpty()) return null;
266	
267	        if (suffix == 'w') {
268	            if (parseWidth(number) == null) return null;
269	        } else {
270	            if (parseDensity(number) == null) return null;
271	        }
272	        return " " + descriptor;
273	    }
274	
275	    /**
276	     Parse a strict width descriptor's integer: one or more ASCII decimal digits with no sign, decimal point, or
277	     exponent, whose value is strictly positive and fits a long. Zero, leading-sign, fractional, and overflowing
278	     values are invalid.
279	     */
280	    private static Long parseWidth(String s) {
281	        long value = 0;
282	        for (int i = 0; i < s.length(); i++) {
283	            char c = s.charAt(i);
284	            if (c < '0' || c > '9') return null;
285	            int digit = c - '0';
286	            if (value > (Long.MAX_VALUE - digit) / 10) return null; // overflow
287	            value = value * 10 + digit;
288	        }
289	        return value == 0L ? null : value;
290	    }
291	
292	    /** Parse a finite strictly-positive floating-point number matching the HTML valid floating-point number grammar. */
293	    private static Double parseDensity(String s) {
294	        int i = 0;
295	        if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
296	            if (s.charAt(i) == '-') return null;
297	            i++;
298	        }
299	        int intDigits = 0;
300	        while (i < s.length() && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
301	        int fracDigits = 0;
302	        if (i < s.length() && s.charAt(i) == '.') {
303	            i++;
304	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { fracDigits++; i++; }
305	        }
306	        // grammar: digits before the optional dot, or digits after it (".5"); a lone "." is invalid
307	        if (intDigits == 0 && fracDigits == 0) return null;
308	        if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
309	            i++;
310	            if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
311	            int exponentDigits = 0;
312	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { exponentDigits++; i++; }
313	            if (exponentDigits == 0) return null;
314	        }
315	        if (i != s.length()) return null; // trailing junk
316	        try {
317	            double value = Double.parseDouble(s);
318	            // the descriptor must be a strictly positive finite number: zero, negatives, NaN, and infinity are invalid
319	            if (!(value > 0d) || Double.isNaN(value) || Double.isInfinite(value)) return null;
320	            return value;
321	        } catch (NumberFormatException e) {
322	            return null;
323	        }
324	    }
325	
326	    private static boolean isAsciiDigit(char c) {
327	        return c >= '0' && c <= '9';
328	    }
329	
330	    /**
331	     Check one candidate URL against the safelist's protocol policy and return the URL spelling to emit.
332	     <p>
333	     Character references have already been decoded by the parser, so a URL that still contains an ASCII control
334	     character or newline is rejected outright: such characters cannot occur in a conforming address and are used to
335	     smuggle disguised {@code javascript:} or {@code data:} schemes past a prefix test. Other URLs are resolved and
336	     checked exactly like an ordinary URI attribute such as {@code src}. When relative links are not preserved,
337	     resolvable candidates are emitted in absolute form.
338	     </p>
339	     <p>
340	     Without a document base URI there is nothing to resolve against, and no path may be invented: a scheme-less
341	     root-relative address (a single leading {@code /}, e.g. {@code /assets/a.png}) carries no unsafe scheme, so it
342	     is kept verbatim as input when the policy permits ordinary http(s) references. Scheme-relative ({@code //host}),
343	     in-directory relative, and custom-scheme candidates that cannot be resolved are still dropped, as they are with a
344	     base URI.
345	     </p>
346	     @return the URL to keep (absolute or original spelling), or {@code null} if it must be dropped
347	     */
348	    private static String isSafeUrl(Element el, String url, Safelist safelist) {
349	        if (containsControlChar(url)) return null; // controls, tabs, and newlines can never be part of a safe address
350	
351	        Set<Safelist.Protocol> protocols = safelist.srcsetProtocols(el.normalName());
352	        if (protocols.isEmpty()) return url; // no protocol policy: accept, like an ordinary untyped attribute
353	
354	        String baseUri = el.baseUri();
355	        String resolved = StringUtil.resolve(baseUri, url);
356	        if (resolved.isEmpty()
357	            && (baseUri == null || baseUri.isEmpty())
358	            && isRootRelative(url)
359	            && permitsHttp(protocols)) {
360	            // No document base: a root-relative reference has no scheme to test and must never be joined against a
361	            // fabricated path; keep the input spelling. Anything else unresolvable falls through and is rejected.
362	            return url;
363	        }
364	        String check = resolved;
365	        if (check.isEmpty() && !StringUtil.hasHttpScheme(url)) check = url; // custom schemes checked as written
366	        if (check.isEmpty()) return null; // an unresolvable relative URL with no base is not acceptable
367	
368	        String lc = Normalizer.lowerCase(check);
369	        for (Safelist.Protocol protocol : protocols) {
370	            String prot = protocol.toString();
371	            if (prot.equals("#")) continue; // fragment anchors are not image candidates
372	            if (lc.startsWith(prot)
373	                && lc.length() > prot.length()
374	                && lc.charAt(prot.length()) == ':') {
375	                // Emit the absolute form like an ordinary src value, unless relative links are preserved.
376	                return (!safelist.preserveRelativeLinks() && !resolved.isEmpty()) ? resolved : url;
377	            }
378	        }
379	        return null;
380	    }
381	
382	    /**
383	     A scheme-less root-relative reference: exactly one leading slash. A protocol-relative reference (two leading
384	     slashes) inherits whatever scheme the context supplies and is not root-relative, so it is not retained.
385	     */
386	    private static boolean isRootRelative(String url) {
387	        return url.length() >= 2 && url.charAt(0) == '/' && url.charAt(1) != '/';
388	    }
389	
390	    /** Whether the policy would accept an ordinary same-origin http(s) reference, as a root-relative address becomes. */
391	    private static boolean permitsHttp(Set<Safelist.Protocol> protocols) {
392	        for (Safelist.Protocol protocol : protocols) {
393	            String prot = Normalizer.lowerCase(protocol.toString());
394	            if (prot.equals("http") || prot.equals("https")) return true;
395	        }
396	        return false;
397	    }
398	
399	    private static boolean containsControlChar(String url) {
400	        for (int i = 0; i < url.length(); i++) {
401	            char c = url.charAt(i);
402	            if (c <= 0x1f || c == 0x7f) return true;
403	        }
404	        return false;
405	    }
406	
407	    private static String serialize(List<Candidate> candidates) {
408	        StringBuilder sb = StringUtil.borrowBuilder();
409	        for (int i = 0; i < candidates.size(); i++) {
410	            if (i > 0) sb.append(", ");
411	            // Delimiting quotes were parse-time syntax only; every accepted address is emitted bare. Candidates whose
412	            // bare spelling would not reparse identically (whitespace inside, a leading quote, or a trailing comma)
413	            // are rejected up front by isBareSerializable, so appending them verbatim is safe.
414	            sb.append(candidates.get(i).url);
415	            sb.append(candidates.get(i).descriptor);
416	        }
417	        return StringUtil.releaseBuilder(sb);
418	    }
419	
420	    /**
421	     Whether the accepted URL can be written without delimiting quotes and still parse back as this same single
422	     candidate. It must not contain HTML whitespace (which would start the descriptors and split the address), must
423	     not begin with a quote character (which would make the reparser treat its content as quoted), and must not end in
424	     a comma (which the parser strips as a trailing separator). Addresses failing this are dropped rather than quoted.
425	     */
426	    private static boolean isBareSerializable(String url) {
427	        if (url.isEmpty()) return false;
428	        char first = url.charAt(0);
429	        if (first == '"' || first == '\'') return false;
430	        if (url.charAt(url.length() - 1) == ',') return false;
431	        for (int i = 0; i < url.length(); i++) {
432	            if (StringUtil.isWhitespace(url.charAt(i))) return false;
433	        }
434	        return true;
435	    }
436	
437	    private static final class Candidate {
438	        final String url;
439	        final String descriptor; // normalized as "" or " <descriptor>"
440	
441	        Candidate(String url, String descriptor) {
442	            this.url = url;
443	            this.descriptor = descriptor;
444	        }
445	    }
446	}
