35	final class SizesCleaner {
36	    private SizesCleaner() {}
37	
38	    /**
39	     Determine whether the supplied attribute key is a {@code sizes} attribute that should be handled entry by entry,
40	     rather than treated as an ordinary opaque attribute.
41	     @param key the attribute key to test
42	     @return true if it is a {@code sizes} attribute
43	     */
44	    static boolean isSizes(String key) {
45	        return "sizes".equalsIgnoreCase(key);
46	    }
47	
48	    /**
49	     Clean a {@code sizes} attribute value into a value containing only the acceptable entries, in their original
50	     order. The input is never modified; callers must apply the result themselves.
51	     @param rawValue the original attribute value
52	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no entry survived, in which
53	     case the attribute must be removed rather than left empty
54	     */
55	    static Result clean(String rawValue) {
56	        List<String> accepted = new ArrayList<>();
57	        int dropped = 0;
58	        if (rawValue != null && !rawValue.isEmpty()) {
59	            String value = stripQuotes(rawValue.trim()); // a quote pair wrapping the whole attribute value
60	            int len = value.length();
61	            int pos = 0;
62	
63	            while (pos < len) {
64	                // Splitting loop: collect one entry. Commas separate entries only at depth zero; a comma inside a
65	                // balanced parenthesized region is entry content. An unmatched ')' ends the entry at that point (the
66	                // entry is rejected); an unmatched '(' would otherwise run to the end, so the first comma inside it
67	                // is remembered and used as a resync point when the group never closes, so a following valid entry
68	                // is not swallowed.
69	                int entryStart = pos;
70	                int depth = 0;
71	                int deepComma = -1;
72	                boolean strayClose = false;
73	                while (pos < len) {
74	                    char c = value.charAt(pos);
75	                    if (c == '(') {
76	                        depth++;
77	                    } else if (c == ')') {
78	                        depth--;
79	                        if (depth < 0) strayClose = true;
80	                    } else if (c == ',') {
81	                        if (depth <= 0) break; // top-level separator
82	                        if (deepComma < 0) deepComma = pos; // first separator inside an unclosed group
83	                    }
84	                    pos++;
85	                }
86	
87	                String entry;
88	                if (pos >= len && depth > 0 && deepComma >= 0) {
89	                    // the group never closed: reject the run up to its first inner comma, and reparse every later
90	                    // comma-separated chunk as its own entry, so a trailing legal entry is not swallowed
91	                    entry = value.substring(entryStart, deepComma);
92	                    pos = deepComma;
93	                } else {
94	                    entry = value.substring(entryStart, pos);
95	                }
96	                boolean balanced = depth == 0 && !strayClose;
97	
98	                String normalized = validateEntry(entry, balanced);
99	                if (normalized != null) accepted.add(normalized);
100	                else if (!entry.trim().isEmpty() || !balanced) dropped++;
101	
102	                if (pos < len && value.charAt(pos) == ',') pos++; // consume the separator
103	            }
104	        }
