106	        if (accepted.isEmpty()) return new Result(null, dropped, true);
107	        return new Result(join(accepted), dropped, false);
108	    }
109	
110	    /** The outcome of cleaning a sizes attribute: the rewritten {@code value} (or null) and statistics. */
111	    static final class Result {
112	        final String value;
113	        final int droppedEntries;
114	        final boolean removed;
115	
116	        private Result(String value, int droppedEntries, boolean removed) {
117	            this.value = value;
118	            this.droppedEntries = droppedEntries;
119	            this.removed = removed;
120	        }
121	    }
122	
123	    /**
124	     Validate one raw entry and return its trimmed spelling, or {@code null} when it is malformed. {@code balanced}
125	     reports whether the collected run ended at parenthesis depth zero; an unbalanced run can never be a valid media
126	     condition or length.
127	     <p>
128	     A media condition may span several parenthesized groups joined by keywords ({@code (min-width: 30em) and
129	     (orientation: landscape)}), so the length is located at the end of the entry: either a whitespace-free scalar
130	     suffix, or a balanced {@code calc(...)} group. Anything before it is the optional media condition.
131	     </p>
132	     */
133	    private static String validateEntry(String entry, boolean balanced) {
134	        String trimmed = stripQuotes(entry.trim()); // a quote pair delimiting this single entry
135	        if (trimmed.isEmpty() || !balanced) return null;
136	        if (containsUnsafeChar(trimmed)) return null;
137	        if (containsScriptFragment(trimmed)) return null;
138	
139	        int lengthStart = findLengthStart(trimmed);
140	        if (lengthStart < 0) return null;
141	
142	        String length = trimmed.substring(lengthStart).trim();
143	        if (!isValidLength(length)) return null;
144	
145	        if (lengthStart > 0) {
146	            String condition = trimmed.substring(0, lengthStart);
147	            // the condition and the length must be separated by whitespace
148	            if (!StringUtil.isWhitespace(condition.charAt(condition.length() - 1))) return null;
149	            if (!isValidMediaCondition(condition.trim())) return null;
150	        }
151	        return trimmed;
152	    }
153	
154	    /**
155	     Return the index at which the trailing length begins, or {@code -1} when the entry does not end in a recognizable
156	     length. A {@code calc(...)} length ends in a balanced {@code )} whose matching {@code (} is preceded by the word
157	     {@code calc} at a token boundary; any other ending must be a single whitespace-free scalar token.
158	     */
159	    private static int findLengthStart(String s) {
160	        int n = s.length();
161	        if (s.charAt(n - 1) == ')') {
162	            int depth = 0;
163	            int i = n - 1;
164	            do {
165	                char c = s.charAt(i);
166	                if (c == ')') depth++;
167	                else if (c == '(') depth--;
168	                i--;
169	            } while (i >= 0 && depth > 0);
170	            int open = i + 1; // index of the matching '('
171	            int wordStart = open;
172	            while (wordStart > 0 && isAsciiLetter(s.charAt(wordStart - 1))) wordStart--;
173	            if (open - wordStart == 4 && s.regionMatches(true, wordStart, "calc", 0, 4)
174	                && (wordStart == 0 || StringUtil.isWhitespace(s.charAt(wordStart - 1)))) {
175	                return wordStart;
176	            }
