244	     */
245	    private static boolean isValidCalcBody(String body) {
246	        String s = body.trim();
247	        if (s.isEmpty()) return false;
248	        char first = s.charAt(0);
249	        if (first == '-' || first == '+' || first == '*' || first == '/') return false;
250	
251	        int depth = 0;
252	        int i = 0;
253	        int n = s.length();
