259	                if (prevOperand) return false; // an operand must be followed by an operator, not a group
260	                depth++;
261	                i++;
262	                continue;
263	            }
264	            if (c == ')') {
265	                depth--;
266	                if (depth < 0 || !prevOperand) return false; // empty group or unbalanced close
267	                i++;
268	                continue;
269	            }
270	            if (c == '+' || c == '-' || c == '*' || c == '/') {
271	                if (!prevOperand) return false; // missing left operand (also rejects doubled operators)
272	                prevOperand = false;
273	                i++;
274	                continue;
275	            }
276	            if (isAsciiLetter(c)) {
277	                // the only word legal at an operand position is a nested calc(...): a balanced group over the same
278	                // grammar. Any other word (url, expression, attr, an unknown unit spelling, ...) is rejected.
279	                if (!s.regionMatches(true, i, "calc(", 0, 5)) return false;
280	                int close = matchingClose(s, i + 5);
281	                if (close < 0 || !isValidCalcBody(s.substring(i + 5, close))) return false;
282	                i = close + 1;
283	                if (i < n) {
284	                    char next = s.charAt(i);
285	                    if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
286	                        && next != '/' && next != ')') return false;
287	                }
288	                prevOperand = true;
289	                continue;
290	            }
291	            // otherwise a scalar operand: a non-negative number with an optional recognized unit
292	            int numEnd = readNumber(s, i);
293	            if (numEnd == i) return false;
294	            int afterUnit = readUnit(s, numEnd);
295	            if (afterUnit != numEnd) {
296	                i = afterUnit; // a unit followed the number
297	            } else {
298	                i = numEnd; // bare number (legal inside calc), but never a bare word or unknown unit
299	                if (i < n && isAsciiLetter(s.charAt(i))) return false;
300	            }
301	            // the operand must end at whitespace, an operator, a parenthesis, or the end of the body
302	            if (i < n) {
303	                char next = s.charAt(i);
304	                if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
305	                    && next != '/' && next != ')') return false;
306	            }
307	            prevOperand = true;
308	        }
309	        return depth == 0 && prevOperand;
310	    }
311	
312	    /** Read a non-negative decimal number ({@code 0}, {@code 12}, {@code 1.5}, {@code .5}); no sign or exponent. */
313	    private static int readNumber(String s, int start) {
314	        int i = start;
315	        int n = s.length();
316	        int digits = 0;
317	        while (i < n && isAsciiDigit(s.charAt(i))) { digits++; i++; }
318	        if (i < n && s.charAt(i) == '.') {
319	            i++;
320	            int frac = 0;
321	            while (i < n && isAsciiDigit(s.charAt(i))) { frac++; i++; }
322	            if (frac == 0) return start; // a trailing or fraction-less dot is not a number
323	        } else if (digits == 0) {
324	            return start;
325	        }
326	        return i;
327	    }
