329	    /** Read a recognized length unit starting at {@code start}; return the index just past it, or {@code start}. */
330	    private static int readUnit(String s, int start) {
331	        int n = s.length();
332	        if (start < n && s.charAt(start) == '%') return start + 1;
333	        String[] units = {"vmin", "vmax", "rem", "vw", "vh", "em", "px", "ch", "ex"};
334	        for (String unit : units) {
335	            int end = start + unit.length();
336	            if (end <= n && s.regionMatches(true, start, unit, 0, unit.length())) return end;
337	        }
338	        return start;
339	    }
340	
341	    /** A plain scalar length: a non-negative decimal number immediately followed by a recognized unit. */
342	    private static boolean isScalarLength(String s) {
343	        int numEnd = readNumber(s, 0);
344	        if (numEnd == 0) return false;
345	        int unitEnd = readUnit(s, numEnd);
346	        return unitEnd != numEnd && unitEnd == s.length();
347	    }
348	
349	    /** Given the index just inside a {@code (} group, return the index of its matching {@code )}, or {@code -1}. */
350	    private static int matchingClose(String s, int start) {
351	        int depth = 1;
352	        for (int i = start; i < s.length(); i++) {
353	            char c = s.charAt(i);
354	            if (c == '(') depth++;
355	            else if (c == ')') {
356	                depth--;
357	                if (depth == 0) return i;
358	            }
359	        }
360	        return -1;
361	    }
362	
363	    private static boolean isAsciiDigit(char c) {
364	        return c >= '0' && c <= '9';
365	    }
366	
367	    private static boolean isAsciiLetter(char c) {
368	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
369	    }
370	
371	    /**
372	     Reject characters that can never appear in a valid entry: control characters (other than HTML whitespace),
373	     quotes, semicolons, and braces. These are the characters that could smuggle stylesheet or script content through
374	     a length or media condition.
