376	    private static boolean containsUnsafeChar(String s) {
377	        for (int i = 0; i < s.length(); i++) {
378	            char c = s.charAt(i);
379	            if (c == '"' || c == '\'' || c == ';' || c == '{' || c == '}') return true;
380	            if (c <= 0x1f && !StringUtil.isWhitespace(c)) return true;
381	            if (c == 0x7f) return true;
