388	     valid in a media condition or length, and a script scheme name (optionally broken up by whitespace or an HTML
389	     entity-decoded tab, e.g. {@code java&Tab;script:}) must never survive. Whitespace is flattened before the
390	     substring test so spacing inside a scheme name cannot hide it.
391	     */
392	    private static boolean containsScriptFragment(String s) {
393	        String lc = s.toLowerCase();
394	        if (lc.contains("url(")) return true;
395	        String flattened = StringUtil.normaliseWhitespace(lc).replace(" ", "");
396	        return flattened.contains("javascript:") || flattened.contains("vbscript:")
397	            || flattened.contains("livescript:") || flattened.contains("data:");
398	    }
399	
400	    /**
401	     Strip a single pair of matching delimiting quotes wrapping the whole text. The delimiters are parse-time syntax
402	     only; they are removed only when the same quote does not also occur inside the text (that is per-entry quoting,
403	     handled entry by entry), and a quote anywhere else is left in place and rejected by entry validation rather than
404	     treated as syntax.
405	     */
406	    private static String stripQuotes(String s) {
407	        if (s.length() >= 2) {
408	            char first = s.charAt(0);
409	            char last = s.charAt(s.length() - 1);
410	            if ((first == '"' || first == '\'') && first == last
411	                && s.indexOf(first, 1) == s.length() - 1) {
412	                return s.substring(1, s.length() - 1);
413	            }
414	        }
415	        return s;
416	    }
417	
418	    private static String join(List<String> entries) {
419	        StringBuilder sb = StringUtil.borrowBuilder();
420	        for (int i = 0; i < entries.size(); i++) {
421	            if (i > 0) sb.append(", ");
