10	/**
11	 Tests for per-entry cleaning of {@code sizes} attributes in the {@link Cleaner}, on {@code img} and {@code source}
12	 elements.
13	 */
14	public class SizesCleanerTest {
15	
16	    private static Safelist safelist() {
17	        return Safelist.relaxed()
18	            .addTags("picture", "source")
