/**
 Validate the media condition text. It must be non-empty (more than parentheses and whitespace), hold only the
 permitted media-query characters, and have balanced nested parentheses; it need not be wrapped in an outer
 parenthesized group, so a bare media type such as {@code screen} is acceptable. No semicolons, braces, quotes,
 or other punctuation that could carry stylesheet or script content; a script scheme smuggled in with whitespace
 inside its name is also rejected.
 */
private static boolean isValidMediaCondition(String condition) {
    String s = condition.trim();
    if (s.isEmpty()) return false;
    int depth = 0;
    boolean hasContent = false;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            depth++;
        } else if (c == ')') {
            depth--;
            if (depth < 0) return false;
        } else if (!isMediaConditionChar(c)) {
            return false;
        } else if (!StringUtil.isWhitespace(c)) {
            hasContent = true; // "()" or "( )" is not a media condition
        }
    }
    return depth == 0 && hasContent;
}

