package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class TempSizesProbeTest {
    private static Safelist sl() {
        return Safelist.relaxed().addTags("picture", "source")
            .addAttributes("img", "srcset", "sizes")
            .addAttributes("source", "srcset", "sizes", "media", "type")
            .addProtocols("img", "srcset", "http", "https")
            .addProtocols("source", "srcset", "http", "https");
    }
    static String sz(String v) {
        Document d = Jsoup.parseBodyFragment("<img sizes='" + v + "'>");
        return new Cleaner(sl()).clean(d).expectFirst("img").attr("sizes");
    }

    @Test void probe() {
        // bare media types accepted per spec
        assertEquals("screen 50vw, 100vw", sz("screen 50vw, 100vw"));
        assertEquals("only screen and (min-width: 30em) 50vw", sz("only screen and (min-width: 30em) 50vw"));
        // injection vectors still rejected even with a bare type
        for (String bad : new String[]{
            "screen; 50vw", "screen { 50vw", "screen url(http://x) 50vw", "screen javascript:alert(1) 50vw",
            "screen 50vw; 100vw", "(x) 50vw" /* stray open */ , "a) 50vw", "screen 50vw)",
        }) {
            String r = sz(bad + ", 100vw");
            assertFalse(r.contains("screen;") || r.contains("{") || r.contains("url(") || r.contains("javascript"),
                "injection survived: " + bad + " -> " + r);
        }
        // dedupe verbatim
        assertEquals("100vw", sz("100vw, 100vw ,100vw"));
        // differently-cased calc spellings are distinct verbatim entries (both kept)
        assertEquals("calc(100vw - 20px), CALC(100VW - 20PX)", sz("calc(100vw - 20px), CALC(100VW - 20PX)"));
        // empty () alone rejected
        assertEquals("", sz("() 50vw"));
        // slash/bang outside charset rejected
        assertEquals("100vw", sz("(r: 1/2) 50vw, 100vw"));
        // C1 controls rejected
        assertEquals("100vw", sz("screen 50vw, 100vw"));
    }
}

